<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);$owner=rxp_target_reseller($ctx);$dir=rxp_bot_dir($pdo,$owner);$file=$dir?$dir.'/style.json':'';$defaults=['enabled'=>true,'buy'=>'success','test'=>'warning','my_service'=>'primary','wallet'=>'primary','support'=>'secondary','admin'=>'danger','back'=>'default','payment_confirm'=>'success','payment_add_balance'=>'primary','payment_back'=>'default','product_item'=>'default','category_item'=>'default','panel_location'=>'primary','custom_volume'=>'warning'];$d=($file&&is_file($file))?array_merge($defaults,json_decode((string)file_get_contents($file),true)?:[]):$defaults;$flash='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$dir)rxp_abort(409,'ربات اختصاصی وجود ندارد.');$d['enabled']=isset($_POST['enabled']);foreach($defaults as $k=>$v)if($k!=='enabled'){$x=(string)($_POST[$k]??'default');$d[$k]=in_array($x,['primary','success','danger','warning','secondary','default'],true)?$x:'default';}file_put_contents($file,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);rxp_audit($pdo,$ctx,'button_colors.update',$owner);$flash='رنگ‌بندی ذخیره شد.';}rxp_layout_start($ctx,'رنگ دکمه‌ها','button_colors.php');rxp_flash($flash);?>
<h1 class="rxp-title">رنگ‌بندی دکمه‌ها</h1><?php if($ctx['role']==='super'):?><div class="rxp-card"><form method="get"><select name="owner" onchange="this.form.submit()"><?php foreach($ctx['scope_ids'] as $id):?><option value="<?=$id?>" <?=$owner===$id?'selected':''?>>نماینده #<?=$id?></option><?php endforeach;?></select></form></div><?php endif;?><?php if(!$dir):?><div class="rxp-flash err">ربات اختصاصی وجود ندارد.</div><?php else:?><div class="rxp-card"><form method="post"><input type="hidden" name="owner" value="<?=rxp_h($owner)?>"><label class="rxp-muted"><input type="checkbox" name="enabled" <?=$d['enabled']?'checked':''?>> فعال</label><div class="rxp-grid"><?php foreach($defaults as $k=>$v):if($k==='enabled')continue;?><div class="rxp-field"><label><?=rxp_h($k)?></label><select name="<?=$k?>"><?php foreach(['default','primary','success','warning','danger','secondary'] as $x):?><option <?=$d[$k]===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><?php endforeach;?></div><button class="rxp-btn">ذخیره</button></form></div><?php endif;?><?php rxp_layout_end();
